import{_ as r,o,c as e,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"电控方向","description":"","frontmatter":{},"headers":[],"relativePath":"guide/electronics.md","filePath":"guide/electronics.md"}'),l={name:"guide/electronics.md"};function i(n,t,s,d,h,g){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="电控方向" tabindex="-1">电控方向 <a class="header-anchor" href="#电控方向" aria-label="Permalink to &quot;电控方向&quot;">​</a></h1><blockquote><p>⚡ 负责机器人的 <strong>嵌入式系统开发、电机控制、传感器数据采集、通信实现</strong></p></blockquote><hr><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><h3 id="第一阶段-基础入门" tabindex="-1">第一阶段：基础入门 <a class="header-anchor" href="#第一阶段-基础入门" aria-label="Permalink to &quot;第一阶段：基础入门&quot;">​</a></h3><ol><li><strong>C 语言基础</strong>：指针、结构体、内存管理</li><li><strong>STM32 入门</strong>：GPIO、定时器、中断、串口通信</li><li><strong>电路基础</strong>：基本电路分析、常见传感器原理</li><li><strong>开发工具链</strong>：Keil / STM32CubeIDE / CLion</li></ol><h3 id="第二阶段-专业进阶" tabindex="-1">第二阶段：专业进阶 <a class="header-anchor" href="#第二阶段-专业进阶" aria-label="Permalink to &quot;第二阶段：专业进阶&quot;">​</a></h3><ol><li><strong>PID 控制</strong>：位置式/增量式 PID、参数整定</li><li><strong>CAN 通信</strong>：CAN 总线协议、电机通信（DJI 电机协议）</li><li><strong>FreeRTOS</strong>：任务调度、消息队列、信号量</li><li><strong>电机控制</strong>：M3508/M2006/GM6020 电机驱动</li></ol><h3 id="第三阶段-实战应用" tabindex="-1">第三阶段：实战应用 <a class="header-anchor" href="#第三阶段-实战应用" aria-label="Permalink to &quot;第三阶段：实战应用&quot;">​</a></h3><ol><li><strong>底盘控制</strong>：麦克纳姆轮解算、遥控器解析、功率限制（RM2027：英雄600W）</li><li><strong>云台控制</strong>：双轴云台稳定、IMU 姿态解算</li><li><strong>发射控制</strong>：摩擦轮调速（RM2027：42mm 热量管理+冷却机制）、拨弹控制</li><li><strong>系统联调</strong>：裁判系统对接（UDP + MQTT/ProtoBuf）、UI 显示、RJ45 千兆通信</li></ol><hr><h2 id="硬件平台" tabindex="-1">硬件平台 <a class="header-anchor" href="#硬件平台" aria-label="Permalink to &quot;硬件平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>硬件</th><th>说明</th></tr></thead><tbody><tr><td><strong>STM32F407/F427</strong></td><td>主控芯片（常用）</td></tr><tr><td><strong>DJI M3508</strong></td><td>减速电机（底盘）</td></tr><tr><td><strong>DJI M2006</strong></td><td>减速电机（云台/拨弹）</td></tr><tr><td><strong>DJI GM6020</strong></td><td>无刷直驱电机（云台）</td></tr><tr><td><strong>DJI C620/C610</strong></td><td>电调</td></tr><tr><td><strong>MPU6050/ICM20602</strong></td><td>IMU 惯性测量单元</td></tr></tbody></table><hr><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><ul><li><strong>STM32 教程</strong>：正点原子/野火系列教程</li><li><strong>PID 控制</strong>：知乎 &quot;PID 控制算法原理&quot;</li><li><a href="https://cdn-hz.robomaster.com/tem/RoboMaster%E5%BC%80%E5%8F%91%E7%89%88%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C.pdf" target="_blank" rel="noreferrer">RoboMaster 开发板用户手册</a></li><li><a href="https://www.robomaster.com/zh-CN/products/components/referee" target="_blank" rel="noreferrer">RM 裁判系统用户手册</a></li></ul><hr><h2 id="新人任务清单" tabindex="-1">新人任务清单 <a class="header-anchor" href="#新人任务清单" aria-label="Permalink to &quot;新人任务清单&quot;">​</a></h2><ul><li>[ ] 搭建 STM32 开发环境（CubeIDE 或 Keil）</li><li>[ ] 跑通一个 LED 闪烁 + 串口打印程序</li><li>[ ] 驱动一个电机（M3508）并实现速度闭环</li><li>[ ] 理解 CAN 总线通信并读取电机反馈数据</li><li>[ ] 实现 PID 速度/位置控制</li><li>[ ] 完成一次底盘运动控制实验</li></ul>',19)])])}const b=r(l,[["render",i]]);export{u as __pageData,b as default};
